INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ein Unternehmen gemäß DSGVO technische Maßnahmen zur Datensicherheit umsetzen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 32 DSGVO fordert technische und organisatorische Maßnahmen"}, {"text": "Nein", "correct": false, "because": "Pflicht ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Daten ohne Sicherheitsmaßnahmen rechtmäßig verarbeitet werden?', 2, '[{"text": "Ja", "correct": false, "because": "Datensicherheit ist Voraussetzung gemäß DSGVO"}, {"text": "Nein", "correct": true, "because": "Verstoß gegen Art. 32 DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Datensicherheit auch für Auszubildende im IT-Betrieb relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Alle Mitarbeiter müssen Datenschutz einhalten"}, {"text": "Nein", "correct": false, "because": "Gilt für alle im Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Sicherheitsmaßnahmen regelmäßig überprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 32 DSGVO verlangt fortlaufende Anpassung"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Überprüfung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Verstoß gegen die Datensicherheit Bußgelder nach sich ziehen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 83 DSGVO sieht Bußgelder vor"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind möglich"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage fordert die Gewährleistung der Datensicherheit?', 2, '[{"text": "Art. 32 DSGVO", "correct": true, "because": "Regelt technische und organisatorische Maßnahmen"}, {"text": "§ 13 BBiG", "correct": false, "because": "Regelt Ausbildungspflichten"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Datensicherheit in einem IT-Betrieb?', 3, '[{"text": "Schutz personenbezogener Daten", "correct": true, "because": "Primäres Ziel der DSGVO"}, {"text": "Erhöhung der Produktivität", "correct": false, "because": "Kein Datenschutzziel"}, {"text": "Kostensenkung", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Datensicherheit im Unternehmen primär verantwortlich?', 2, '[{"text": "Der Verantwortliche (z. B. Arbeitgeber)", "correct": true, "because": "Art. 24 DSGVO legt Verantwortung fest"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nur mitwirkend"}, {"text": "Die Berufsschule", "correct": false, "because": "Keine betriebliche Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zur Gewährleistung der Datensicherheit?', 3, '[{"text": "Verschlüsselung von Daten", "correct": true, "because": "Technische Maßnahme gemäß Art. 32 DSGVO"}, {"text": "Öffentliche Datenspeicherung", "correct": false, "because": "Verstoß gegen Datenschutz"}, {"text": "Keine Sicherheitsupdates", "correct": false, "because": "Gefährdet Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei einem Verstoß gegen die Datensicherheit?', 2, '[{"text": "Mögliche Bußgelder und Schadensersatz", "correct": true, "because": "Art. 82 und 83 DSGVO"}, {"text": "Automatische Kündigung", "correct": false, "because": "Keine direkte Folge"}, {"text": "Keine Konsequenz", "correct": false, "because": "Sanktionen vorgesehen"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Gewährleistung der Datensicherheit?', 4, '[{"text": "Datenverschlüsselung", "correct": true, "because": "Schutz vor unbefugtem Zugriff"}, {"text": "Regelmäßige Backups", "correct": true, "because": "Datensicherung"}, {"text": "Offene WLAN-Netze", "correct": false, "because": "Gefährdet Sicherheit"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Beschränkt Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen kann ein Verstoß gegen die Datensicherheit haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Art. 83 DSGVO"}, {"text": "Reputationsverlust", "correct": true, "because": "Vertrauensschaden"}, {"text": "Höhere Produktivität", "correct": false, "because": "Keine positive Folge"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Art. 82 DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln die Datensicherheit?', 4, '[{"text": "Art. 32 DSGVO", "correct": true, "because": "Technische Maßnahmen"}, {"text": "Art. 24 DSGVO", "correct": true, "because": "Verantwortlichkeit"}, {"text": "§ 13 BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "BDSG", "correct": true, "because": "Nationale Ergänzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte müssen bei der Datensicherheit beachtet werden?', 3, '[{"text": "Schutz vor Datenverlust", "correct": true, "because": "Ziel der Sicherheitsmaßnahmen"}, {"text": "Verhinderung unbefugten Zugriffs", "correct": true, "because": "Art. 32 DSGVO"}, {"text": "Öffentliche Datenfreigabe", "correct": false, "because": "Verstoß gegen Datenschutz"}, {"text": "Regelmäßige Überprüfung", "correct": true, "because": "Anpassung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sind an der Datensicherheit beteiligt?', 3, '[{"text": "Verantwortlicher (Arbeitgeber)", "correct": true, "because": "Art. 24 DSGVO"}, {"text": "Datenschutzbeauftragter", "correct": true, "because": "Unterstützt Umsetzung"}, {"text": "Kunden", "correct": false, "because": "Keine interne Rolle"}, {"text": "Mitarbeiter", "correct": true, "because": "Müssen Maßnahmen einhalten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Datensicherheit ist gesetzlich vorgeschrieben. b) Sie betrifft nur externe Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) DSGVO, b) falsch (auch interne Daten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschlüsselung ist eine Sicherheitsmaßnahme. b) Datensicherheit ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (DSGVO-Pflicht)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Verstoß kann Bußgelder nach sich ziehen. b) Auszubildende sind nicht verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) Art. 83 DSGVO, b) falsch (mitwirkend)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Regelmäßige Überprüfung ist erforderlich. b) Datensicherheit betrifft nur große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) Art. 32 DSGVO, b) falsch (alle Unternehmen)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backups sind Teil der Datensicherheit. b) Datensicherheit schützt vor unbefugtem Zugriff.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Datensicherung, b) Art. 32 DSGVO"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
